def tx(v):return s.latex(s.simplify(v))
def add(n,k,e,steps,ans,parts=''):
 b.add(n,636 if n<=11 else 637,('확률','Probability'),(k,e),steps,(ans,ans),list(parts),check=('밀도는 음수가 아니고 전체 적분이1인지 확인한다. 확률은0과1 사이이며 평균·중앙값·최빈값을 구분한다.','Check nonnegativity and total integral1.Probabilities must lie in[0,1]; distinguish mean,median and mode.'));b.E[n]['conceptHref']='../../calc1/index.html'
