def normtext(v):
 if isinstance(v,str):
  chunks=re.split(r'(\\\(.*?\\\)|\\\[.*?\\\])',v,flags=re.S);return ''.join(z if i%2 else z.replace('<',r'\(\lt\)')for i,z in enumerate(chunks))
 if isinstance(v,list):return[normtext(z)for z in v]
 if isinstance(v,dict):return{k:normtext(z)for k,z in v.items()}
 return v
